(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.012+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.014-t*0.2)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.0],
    [320+Math.cos(t*0.48)*105, 165+Math.sin(t*0.65)*55, 0.095, 1.75, 0.8],
    [240+Math.sin(t*0.28+2)*145, 115+Math.cos(t*0.45+1)*95, 0.055, 2.4, 1.6],
    [115+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.55, 2.4],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 3.2],
    [240+Math.cos(t*0.32+5)*125, 205+Math.sin(t*0.52)*85, 0.085, 1.95, 4.0],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.13, 1.3, 4.8],
    [400+Math.cos(t*0.42+2)*60, 200+Math.sin(t*0.78+4)*55, 0.1, 2.2, 5.6]
  ];
  let aS=0, iS=0, cross=0, harm=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,ph]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wA=Math.sin(d*f-t*sp+ph);
    const wI=Math.sin(d*f*0.7+t*sp*0.55+ph+1.5);
    aS+=wA; iS+=wI;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2,ph2]=src[j];
      const d2=Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross+=Math.sin((d*f+d2*f2)*0.5-t*(sp+sp2)*0.5+ph+ph2)*0.12;
    }
    harm+=Math.sin(d*f*0.35-t*sp*0.3+ph*2)*0.5;
  }
  const n=src.length, act=aS/n, inh=iS/n, crs=cross, hrm=harm/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.18+Math.sin((sx-sy)*0.095-t*1.8)*0.18;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.038+ang*4.5-t*1.1)+Math.sin(dist*0.06-ang*2-t*2))*0.28;
  const fine=(Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)+Math.sin((sx-sy)*0.2+t*4)*0.5)*0.08;
  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral+crs*0.6+hrm*0.2+fine)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.45+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.4)*0.25;
  const ridge=Math.abs(Math.sin(dist*0.08-ang*2+t*0.5))<0.08?0.15:0;
  const blend=reaction*0.65+cell*0.2+ridge, v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,82],[18,88,108],[24,135,128],[65,168,130],[160,185,80],[210,170,58],[220,125,65],[195,75,72],[140,42,65],[75,22,55],[35,12,48],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.8)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*90))|0
  ];
}
